      isArrayOfTables = true;
      const endIdx = trimmed.indexOf(']]');
      if (endIdx === -1) {
        throw new ParseError(lineNum, 'unterminated table header');
      }
      headerContent = trimmed.slice(2, endIdx);
      const afterHeader = trimmed.slice(endIdx + 2);
      if (afterHeader && !this.isComment(afterHeader)) {
        throw new ParseError(lineNum, 'trailing text after a table header');
      }
    } else if (trimmed.startsWith('[')) {
      const endIdx = trimmed.indexOf(']');
      if (endIdx === -1) {
        throw new ParseError(lineNum, 'unterminated table header');
      }
      headerContent = trimmed.slice(1, endIdx);
      const afterHeader = trimmed.slice(endIdx + 1);
      if (afterHeader && !this.isComment(afterHeader)) {
        throw new ParseError(lineNum, 'trailing text after a table header');
      }
    }

    const path = this.parseDottedName(headerContent, lineNum);

    if (isArrayOfTables) {
      this.handleArrayOfTablesHeader(path, lineNum);
    } else {
      this.handleTableHeader(path, lineNum);
    }
  }

