    const pathStr = path.join('.');
    const pathKey = JSON.stringify(path); // Use serialized path as key

    // Check if this table was already explicitly defined
    if (this.definedTables.has(pathKey)) {
      throw new ParseError(lineNum, `table ${pathStr} is defined twice`);
    }

    // Navigate to the table, creating it if needed
    let current = this.root;
    const wasCreatedOnTheWay = [];

    for (let i = 0; i < path.length; i++) {
      const key = path[i];

      if (!(key in current)) {
        current[key] = {};
