    if (eqIdx === -1) {
      throw new ParseError(lineNum, 'expected key = value');
    }

    const keyPart = line.slice(0, eqIdx).trim();
    const valuePart = line.slice(eqIdx + 1);

    if (!keyPart) {
      throw new ParseError(lineNum, 'expected a name');
    }

    const keys = this.parseDottedName(keyPart, lineNum);
    const valueAndRest = this.parseValue(valuePart, lineNum);

    if (valueAndRest.rest.trim() && !this.isComment(valueAndRest.rest.trim())) {
      throw new ParseError(lineNum, 'trailing text after a value');
