    const parts = [];
    let current = '';
    let i = 0;

    while (i < input.length) {
      const char = input[i];

      if (char === ' ' || char === '\t') {
        i++;
        continue;
      }

      if (char === '.') {
        if (!current) {
          throw new ParseError(lineNum, 'expected a name');
        }
        parts.push(current);
        current = '';
        i++;
        continue;
      }

