    while (i < input.length) {
      const char = input[i];

      // Skip whitespace
      if (char === ' ' || char === '\t') {
        i++;
        continue;
      }

      if (char === '}') {
        return { value: table, rest: input.slice(i + 1) };
      }

      if (state === 'expecting-key') {
        // Parse key = value
        const eqIdx = this.findUnquotedChar(input.slice(i), '=');
        if (eqIdx === -1) {
          throw new ParseError(lineNum, 'expected = in an inline table');
        }

        const keyPart = input.slice(i, i + eqIdx).trim();
        if (!keyPart) {
          throw new ParseError(lineNum, 'expected a name');
        }

        const keys = this.parseDottedName(keyPart, lineNum);
        if (keys.length !== 1) {
          throw new ParseError(lineNum, 'expected a name');
        }

        const key = keys[0];
        if (key in table) {
          throw new ParseError(lineNum, `key ${key} is defined twice`);
        }

        i += eqIdx + 1;

        const valueResult = this.parseValue(input.slice(i), lineNum);
        table[key] = valueResult.value;
        i += input.slice(i).length - valueResult.rest.length;

        state = 'expecting-comma-or-close';
      } else if (state === 'expecting-comma-or-close') {
        if (char === ',') {
          i++;
          state = 'expecting-key';
        } else if (char === '}') {
          return { value: table, rest: input.slice(i + 1) };
        } else {
          throw new ParseError(lineNum, 'expected key = value');
        }
      }
    }

    throw new ParseError(lineNum, 'unterminated inline table');
  }

  findUnquotedChar(str, target) {
    for (let i = 0; i < str.length; i++) {
      if (str[i] === '"' || str[i] === "'") {
        const quote = str[i];
        i++;
        while (i < str.length && str[i] !== quote) {
          if (str[i] === '\\') i++; // Skip escaped char
          i++;
        }
        i++; // Skip closing quote
      } else if (str[i] === target) {
        return i;
      }
    }
    return -1;
  }

  isNameChar(char) {
    return /[A-Za-z0-9_-]/.test(char);
  }

  isWhitespaceOrComment(char) {
    return char === ' ' || char === '\t' || char === '#' || char === ';' || char === '\n';
  }

  isComment(str) {
    const first = str[0];
    return first === '#' || first === ';';
  }
}

export { Parser, ParseError };
