/**
 * The command. `node src/cli.js json` prints the configuration document read
 * from standard input as canonical JSON, and `node src/cli.js keys` prints the
 * path and type of every node in it.
 */

import { Parser, ParseError } from './parser.js';
import { toJSON, toKeys } from './formatter.js';

const args = process.argv.slice(2);

if (args.length !== 1 || !['json', 'keys'].includes(args[0])) {
  process.stderr.write('error: usage: cli.js json|keys\n');
  process.exit(2);
}

const mode = args[0];

// Read from stdin
let input = '';
process.stdin.setEncoding('utf8');

process.stdin.on('data', chunk => {
  input += chunk;
});

process.stdin.on('end', () => {
  try {
    const parser = new Parser(input);
    const document = parser.parse();

    if (mode === 'json') {
      process.stdout.write(toJSON(document));
    } else if (mode === 'keys') {
      const lines = toKeys(document);
      if (lines.length > 0) {
        process.stdout.write(lines.join('\n') + '\n');
      }
    }

    process.exit(0);
  } catch (error) {
    if (error instanceof ParseError) {
      process.stderr.write(`error: line ${error.lineNumber}: ${error.reason}\n`);
    } else {
      process.stderr.write(`error: ${error.message}\n`);
    }
    process.exit(2);
  }
});
