const cli = fileURLToPath(new URL('./src/cli.js', import.meta.url));

function test(name, input, mode) {
  const result = spawnSync(process.execPath, [cli, mode], { 
    encoding: 'utf8', 
    input 
  });
  console.log(`${name}:`);
  if (result.status !== 0) {
    console.log('ERR:', result.stderr.trim());
  } else {
    console.log(result.stdout.trim());
  }
  console.log();
}

// Test dotted keys creating intermediate tables
test('Dotted keys create tables', 'a.b.c = 1\na.b.d = 2', 'json');

// Test that we can't reassign a key
test('Key reassignment error', 'a.b = 1\na.b.c = 2', 'json');

// Test inline tables with dotted names
test('Inline table', 'a = {x.y = 1, x.z = 2}', 'json');

// Test arrays in inline tables
test('Arrays in inline table', 'a = {x = [1, 2]}', 'json');

// Test nested arrays
test('Nested arrays', 'a = [[1, 2], [3, 4]]', 'json');

// Test table within array of tables
test('Table after array of tables', '[[a]]\nb = 1\n[[a]]\nb = 2\n[a.c]\nd = 3', 'json');

// Test that # in quoted value is allowed
test('Hash in quoted string', 'a = "hello#world"', 'json');

// Test comment markers
test('Comment marker test', 'a = 1 # this is a comment', 'json');

// Test invalid trailing text after header
test('Trailing text after header', '[a] invalid', 'json');

// Test negative array index (should work - it's in array indices)
test('Array with negatives', 'a = [-1, -2, -3]', 'json');
